      to = me,
      damage = 2,
    }
  end)
  lu.assertEquals(me.hp, 3)
  FkTest.runInRoom(function ()
    room:throwCard(card, nil, me)
  end)
  lu.assertEquals(me.hp, 4)
end)

return silverLionSkill

