    local n = #cards
    if n > 0 then
      return {
        min_num = n,
        max_num = n,
        pattern = ".|.|.|hand",
        subcards = cards
      }
    end
  end,
  card_filter = Util.FalseFunc,
  view_as = function(self, player, cards)
    local card = Fk:cloneCard("slash")
