    n = math.min(n, 5)
    return player.room:askToSkillInvoke(player, {
      skill_name = lie.name,
      prompt = "#mobile__natu_lie-invoke:::"..n,
    })
  end,
  on_use = function(self, event, target, player, data)
    local room = player.room
    local n = player:usedSkillTimes(lie.name, Player.HistoryTurn)
    n = player:getHandcardNum() - math.min(n, 5)
    if n < 0 then
      player:drawCards(-n, lie.name)
    elseif n > 0 then
      if #room:askToDiscard(player, {
        min_num = n,
        max_num = n,
        skill_name = lie.name,
        cancelable = false,
        include_equip = false,
      }) > 0 and not player.dead then
        local to = room:askToChoosePlayers(player, {
          targets = room.alive_players,
          min_num = 1,
          max_num = 1,
          prompt = "#mobile__natu_lie-damage",
          skill_name = lie.name,
        })
        if #to > 0 then
          room:damage{
            from = player,
            to = to[1],
            damage = 1,
            skillName = lie.name,
          }
        end
      end
    end
  end,
})

return lie

