    return table.concat(table.map(value, function(suit)
      return Fk:translate(Card.getSuitString({ suit = suit }, true))
    end), "")
  end,
}
-- 在脸上显示角色武将名（若有副将，改为显示位置）
-- 传入值：角色ID
Fk:addQmlMark{
  name = "chara",
